require_once __DIR__.'/../core/Auth.php';require_once __DIR__.'/../core/Response.php';Auth::requireLogin();if(!Auth::isAdmin()&&!Auth::isEmployee()&&!Auth::can('payroll.own')){http_response_code(403);exit('دسترسی غیرمجاز است.');}$pageTitle='فیش‌های حقوقی من';$adminExtraStylesheets=['/assets/css/workforce.css'];$rows=Database::fetchAll("SELECT s.*,p.title period_title,p.period_key FROM payroll_slips s JOIN payroll_periods p ON p.id=s.period_id WHERE s.user_id=? AND s.status='published' AND p.status IN ('published','locked') ORDER BY p.year DESC,p.month DESC",[(int)Auth::user()['id']]);require __DIR__.'/../views/partials/admin-header.php';?>
<div class="workforce-head"><div><h1>فیش‌های حقوقی من</h1><p>فقط فیش‌های منتشرشده حساب کاربری شما نمایش داده می‌شود.</p></div></div><section class="card"><div class="table-wrap"><table><thead><tr><th>دوره</th><th>جمع مزایا</th><th>جمع کسورات</th><th>خالص پرداختی</th><th></th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=e($r['period_title'])?></td><td><?=e(format_money($r['total_earnings']))?></td><td><?=e(format_money($r['total_deductions']))?></td><td><strong><?=e(format_money($r['net_pay']))?> ریال</strong></td><td><a class="btn btn-small" href="/employee/payroll-slip.php?id=<?=$r['id']?>">مشاهده</a></td></tr><?php endforeach?><?php if(!$rows):?><tr><td colspan="5">هنوز فیش منتشرشده‌ای برای شما وجود ندارد.</td></tr><?php endif?></tbody></table></div></section><?php require __DIR__.'/../views/partials/admin-footer.php';?>
